      hu: ["Magassága 1194 méter.", "Ponérihouen és Houaïlou határán található.", "Az északi központi hegylánc tagja.", "Jelentős kiterjedésű primer esőerdő borítja.", "A régió fontos víztározó területe.", "Endemikus madárfajok, például a kagu élőhelye."],
      ro: ["Altitudinea este de 1194 metri.", "Situat între Ponérihouen și Houaïlou.", "Parte a lanțului muntos central nordic.", "Acoperit de păduri pluviale primare.", "Rezervor important de apă pentru regiune.", "Habitat pentru păsări endemice, inclusiv kagu."],
      en: ["Elevation stands at 1,194 meters.", "Border peak between Ponérihouen and Houaïlou.", "Member of the northern central range.", "Covered by significant primary rainforest.", "Critical watershed for the local area.", "Habitat for endemic birds like the kagu."],
      es: ["La altitud es de 1194 metros.", "Montaña fronteriza entre Ponérihouen y Houaïlou.", "Parte de la cordilheira montañosa central.", "Alta proporción de selva primaria.", "Importante reserva de agua para la región.", "Presencia de aves endémicas como el kagu."],
      pt: ["A altitude é de 1194 metros.", "Montanha fronteiriça entre Ponérihouen e Houaïlou.", "Parte da cordilheira central.", "Elevada proporção de floresta primária.", "Importante reservatório de água para a região.", "Ocorrência de aves endémicas como o kagu."],
      fr: ["L'altitude est de 1194 mètres.", "Montagne frontalière entre Ponérihouen et Houaïlou.", "Fait partie de la chaîne centrale.", "Forte proportion de forêt primaire.", "Important réservoir d'eau pour la région.", "Présence d'oiseaux endémiques comme le cagou."],
